scene.add(eLab);

const formula = new MathTex({ latex: '\\left(1+\\tfrac{1}{n}\\right)^n \\to e', color: WHITE });
await formula.waitForRender();
formula.scale(0.8);
formula.moveTo([4.3, -1.2, 0]);
