const ns = [1, 2, 3, 4, 6, 12, 24, 52, 100, 365, 1000, 8760, 525600];
const names = ['yearly', 'twice a year', '3 times a year', 'quarterly', 'every 2 months', 'monthly', 'twice a month', 'weekly', '100 times a year', 'daily', '1000 times a year', 'hourly', 'every minute'];

let stair = null, endDot = null, info = null, info2 = null;

function draw(idx) {
  const n = ns[idx];
  const r = 1 + 1 / n;
  if (stair) scene.remove(stair);
  if (endDot) scene.remove(endDot);
  if (info) scene.remove(info);
  if (info2) scene.remove(info2);
  const samples = Math.min(2000, Math.max(400, n * 8));
