  endDot = new Dot({ point: ax.c2p(1, final), color: RED });
  info = new Text({ text: 'Compounded ' + names[idx] + '  (n = ' + n + ')', color: BLUE_B, fontSize: 26 });
  info.moveTo([-1, 3.5, 0]);
  info2 = new Text({ text: 'After 1 year: $' + final.toFixed(6), color: RED_B, fontSize: 26 });
  info2.moveTo([-1, 3.0, 0]);
  scene.add(stair, endDot, info, info2);
}

let cur = 0;
draw(0);

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Compounding frequency', min: 0, max: ns.length - 1, value: 0, step: 1, onChange: (v) => { cur = Math.round(v); draw(cur); } });
controls.addButton({ label: 'Animate', onClick: () => {
  let i = 0;
  const stepFn = () => { draw(i); cur = i; i++; if (i < ns.length) setTimeout(stepFn, 700); };
